-- NiNes Hardware Lab: foundation schema. Apply with `supabase db push`.
create extension if not exists "pgcrypto";
create type public.app_role as enum ('customer','engineer','manager','admin');
create type public.rma_status as enum ('draft','submitted','received','inspection','quoted','approved','diagnosis','repair','testing','qa','ready_to_ship','shipped','closed','cancelled');
create type public.repair_status as enum ('open','on_hold','in_progress','awaiting_parts','testing','complete','unrepairable');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, legal_name text, country_code text, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, organization_id uuid references public.organizations, full_name text, phone text, role public.app_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.equipment (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, manufacturer text not null, model text not null, serial_number text not null, category text, created_at timestamptz not null default now(), unique(organization_id, serial_number));
create table public.rmas (id uuid primary key default gen_random_uuid(), rma_number text not null unique default ('RMA-' || to_char(now(),'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,7))), organization_id uuid not null references public.organizations, requested_by uuid not null references public.profiles, equipment_id uuid references public.equipment, status public.rma_status not null default 'draft', fault_description text not null, priority text not null default 'standard' check (priority in ('standard','urgent','critical')), submitted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.repairs (id uuid primary key default gen_random_uuid(), rma_id uuid not null unique references public.rmas on delete cascade, assigned_engineer_id uuid references public.profiles, status public.repair_status not null default 'open', received_at timestamptz, diagnosis text, repair_notes text, test_results text, warranty_expires_at date, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.rma_events (id uuid primary key default gen_random_uuid(), rma_id uuid not null references public.rmas on delete cascade, actor_id uuid references public.profiles, status public.rma_status not null, note text, created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles, entity_type text not null, entity_id uuid, action text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,full_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.equipment enable row level security; alter table public.rmas enable row level security; alter table public.repairs enable row level security; alter table public.rma_events enable row level security; alter table public.audit_logs enable row level security;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('engineer','manager','admin')); $$;
create policy "profiles readable by self or staff" on public.profiles for select using (id=auth.uid() or public.is_staff()); create policy "users update own profile" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid());
create policy "orgs visible to members" on public.organizations for select using (id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff());
create policy "equipment scoped to organization" on public.equipment for all using (organization_id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff()) with check (organization_id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff());
create policy "rmas scoped to organization" on public.rmas for select using (organization_id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff()); create policy "customers submit organization rmas" on public.rmas for insert with check (requested_by=auth.uid() and organization_id=(select organization_id from public.profiles where id=auth.uid())); create policy "staff manage rmas" on public.rmas for update using (public.is_staff());
create policy "staff manage repairs" on public.repairs for all using (public.is_staff()) with check (public.is_staff()); create policy "repair visible through rma" on public.repairs for select using (exists(select 1 from public.rmas where rmas.id=repairs.rma_id and (rmas.organization_id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff()))); create policy "events visible through rma" on public.rma_events for select using (exists(select 1 from public.rmas where rmas.id=rma_events.rma_id and (rmas.organization_id=(select organization_id from public.profiles where id=auth.uid()) or public.is_staff()))); create policy "staff create events" on public.rma_events for insert with check (public.is_staff()); create policy "staff read audit logs" on public.audit_logs for select using (public.is_staff());
